Could you try this patch on the recent master? I suspect that it's a gnome issue. 

```diff
diff --git a/alacritty/src/display/mod.rs b/alacritty/src/display/mod.rs
index 4dafa80f..ae0e4f11 100644
--- a/alacritty/src/display/mod.rs
+++ b/alacritty/src/display/mod.rs
@@ -980,13 +980,14 @@ impl Display {
 
         // Clearing debug highlights from the previous frame requires full redraw.
         self.swap_buffers();
+        self.swap_buffers();
 
-        if matches!(self.raw_window_handle, RawWindowHandle::Xcb(_) | RawWindowHandle::Xlib(_)) {
+        // if matches!(self.raw_window_handle, RawWindowHandle::Xcb(_) | RawWindowHandle::Xlib(_)) {
             // On X11 `swap_buffers` does not block for vsync. However the next OpenGl command
             // will block to synchronize (this is `glClear` in Alacritty), which causes a
             // permanent one frame delay.
-            self.renderer.finish();
-        }
+            // self.renderer.finish();
+        // }
 
         // XXX: Request the new frame after swapping buffers, so the
         // time to finish OpenGL operations is accounted for in the timeout.

```
